  // ======================= 1. THE SLINGERS, AS FIRST DRAWN =======================
  // The four tribes went back to their first look (soft fur patterns, not the bold red bands). The frames are
  // stored pixel for pixel: SLING_OLD.pal is the palette, each frame is 42x40 rows of palette letters ('.' is
  // empty, 'x~12~' is 12 of x). Frames: 0 idle, 1-4 walk, 5-7 whirl the sling, 8 let go.
  const unrle = (s) => s.replace(/(.)~(\d+)~/g, (m, ch, n) => ch.repeat(+n));
  const slingCache = {};
  D.slinger = (o) => {
    const v = (o && o.v) || 'bands', src = SLING_OLD.fr[v] || SLING_OLD.fr.bands;
    if (!slingCache[v]) slingCache[v] = src.map((str) => {
      const rows = unrle(str).split('|'), c = mk(rows[0].length, rows.length);
      rows.forEach((r, y) => { for (let x = 0; x < r.length; x++) if (r[x] !== '.') px(c.ctx, x, y, SLING_OLD.pal[r.charCodeAt(x) - 48]); });
      return c;
    });
    return slingCache[v].map((f) => { const c = mk(f.width, f.height); c.ctx.drawImage(f, 0, 0); return c; });
  };
  if (A._spCache) Object.keys(A._spCache).forEach((k) => { if (/^jv_(chief|glyph|spiral|zig)$|slinger/.test(k)) delete A._spCache[k]; });

  // ======================= 2. NEW BLOCKS AND WALLS =======================
  const addTile = (d) => { if (RW.T[d.key] != null) return RW.T[d.key]; const id = RW.TILES.length; RW.TILES.push(Object.assign({}, d, { id })); RW.T[d.key] = id; return id; };
  const addWall = (d) => { if (RW.W[d.key] != null) return RW.W[d.key]; const id = RW.WALLS.length; RW.WALLS.push(d); RW.W[d.key] = id; return id; };
  const T_FERN = addTile({ key: 'fern', name: 'Fern', hard: 0, time: 0.05, decor: 'fern', soft: true });
  const T_JFLOWER = addTile({ key: 'jflower', name: 'Jungle Flower', hard: 0, time: 0.05, decor: 'jflower', soft: true });
  const T_LIANA = addTile({ key: 'liana', name: 'Liana', hard: 0, time: 0.25, drop: 'rope', climb: true, decor: 'liana', soft: true });
  const T_WICKER = addTile({ key: 'wicker', name: 'Woven Nest', solid: true, hard: 1, time: 0.5, drop: ['wood', 1, 1], decor: 'wicker' });
  const T_FENCE = addTile({ key: 'fence', name: 'Rail Fence', hard: 1, time: 0.3, drop: ['wood', 1, 1], decor: 'fence' });
  const T_SWING = addTile({ key: 'swingseat', name: 'Log Swing', hard: 1, time: 0.3, drop: ['wood', 1, 2], decor: 'swingseat' });
  const T_ROOTS = addTile({ key: 'groots', name: 'Roots', hard: 0, time: 0.2, drop: ['wood', 1, 1], decor: 'groots', soft: true });
  const T_MOSS = addTile({ key: 'mossstep', name: 'Mossy Stone', solid: true, hard: 2, time: 0.9, drop: 'stone', decor: 'mossstep' });
  const T_DENCHEST = addTile({ key: 'denchest', name: 'Mother\'s Hoard', solid: true, hard: 2, time: 1.4, decor: 'chest', chest: 'vault', loot: 'den', light: [0.45, 0.32, 0.1] });
  const T_LIMB = addTile({ key: 'limb', name: 'Great Limb', solid: true, hard: 2, time: 1.2, drop: ['wood', 2, 3], decor: 'limb' });
  const T_CANOPY = addTile({ key: 'canopy', name: 'Canopy Leaves', hard: 0, time: 0.1, drop: ['leaf', 0, 1], decor: 'canopy', soft: true });
  const T_GLOWCAP = addTile({ key: 'glowcap', name: 'Jungle Mushrooms', hard: 0, time: 0.05, decor: 'glowcap', soft: true, light: [0.5, 0.3, 0.1] });
  const WL_TRUNK = addWall({ key: 'gtrunk', colors: ['#4a3424', '#5e4430', '#3a281c'] });
  const WL_LEAF = addWall({ key: 'gleaf', colors: ['#1c3a1a', '#24481f', '#142c13'] });
  const WL_WICKER = addWall({ key: 'wickerw', colors: ['#6a5034', '#7e6040', '#56402a'] });
  const WL_DEN = addWall({ key: 'denw', colors: ['#4a3a2c', '#56442f', '#3a2c20'] });
  RW.LOOT.den = [['platinum_bar', 2, 5, 0.9], ['crystal_gold', 1, 2, 0.8], ['key_fragment', 1, 1, 0.7], ['crystal_red', 1, 3, 0.6], ['crystal_purple', 1, 2, 0.5], ['scorpion_stinger', 3, 6, 1], ['bronze_bar', 2, 5, 0.6], ['stygian_bar', 1, 2, 0.25]];
  if (!RW.ITEMS.mother_carapace) R.items([
    { id: 'mother_carapace', name: 'Mother\'s Carapace', kind: 'material', icon: { s: 'shard', a: '#8a5a34', b: '#3e2a1e' }, desc: 'A spiked plate from the back of a Mother Scorpion. Heavy, dark, and still a little warm.' },
  ]);

  // ---------- bark: one continuous grain down a whole trunk, round in the light (painted by hand below) ----------
  // The game's wall pass draws these as see-through; the trunks and the back canopy are painted in the hills pass
  // (behind every block), so their grain, moss and knots line up across tiles instead of repeating.
  const blank = mk(TS, TS);
  const baseBuild = A.buildTiles;
  A.buildTiles = function () { const r = baseBuild.apply(this, arguments); [WL_TRUNK, WL_LEAF].forEach((id) => { A.walls[id] = [blank, blank, blank]; }); return r; };
  const BARK = ['#24180f', '#33231a', '#433022', '#56402c', '#6c5238', '#86684a', '#a2845e'];
  const MOSS = ['#263c1c', '#304c22', '#3c5e28', '#4e7232'];
  const barkCache = new Map();
  // a 16x16 piece of trunk: dl/dr = tiles to the trunk's left/right edge, so light wraps round the cylinder
  function barkTile(wx, wy, dl, dr, mossy) {
    const key = (wx & 3) + ',' + (wy & 15) + ',' + Math.min(dl, 9) + ',' + Math.min(dr, 9) + ',' + mossy;
    let c = barkCache.get(key); if (c) return c;
    c = mk(TS, TS); const g = c.ctx; const width = dl + dr + 1;
    for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
      const X = (wx & 3) * TS + x, Y = (wy & 15) * TS + y;
      const u = (dl * TS + x + 0.5) / (width * TS);              // 0..1 across the trunk
      const round = Math.sin(Math.PI * u);                         // cylinder
      let lv = 1 + round * 3.2 + (u < 0.45 ? 0.9 : -0.2);          // lit from the left
      const groove = RW.noise2(X / 3.2, Y / 26, 71);              // long vertical ridges
      const fine = RW.noise2(X / 1.4, Y / 7, 73);
      if (groove < 0.34) lv -= 1.6; else if (groove > 0.66) lv += 0.7;
      if (fine > 0.78) lv += 0.6; else if (fine < 0.2) lv -= 0.5;
      // knots: dark eyes with a light rim, every so often
      const kx = 10 + Math.floor(RW.hash2(Math.floor(Y / 128), wx >> 2, 74) * 44), ky = 64 + Math.floor(Y / 128) * 128, kd = Math.hypot((X - kx) / 3, (Y - ky) / 5) + (RW.hash2(Math.floor(Y / 128), wx >> 2, 76) < 0.5 ? 9 : 0);
      if (kd < 1) lv = 0.4; else if (kd < 1.6) lv += 1.1;
      let col = BARK[RW.clamp(Math.round(lv), 0, 6)];
      // moss creeps up the shaded side and settles in the grooves
      if (mossy) { const m = RW.noise2(X / 6, Y / 9, 75); if ((u > 0.6 && m > 0.6) || (groove < 0.3 && m > 0.7)) col = MOSS[RW.clamp(Math.round(m * 4 - 1.2 + round), 0, 3)]; }
      px(g, x, y, col);
    }
    barkCache.set(key, c); return c;
  }
  const LEAFB = ['#0c1e0e', '#123016', '#18401c', '#215224', '#2c662c'];
  const leafBCache = new Map();
  function backLeafTile(wx, wy, open) {
    const key = (wx & 7) + ',' + (wy & 7) + ',' + open; let c = leafBCache.get(key); if (c) return c;
    c = mk(TS, TS); const g = c.ctx;
    for (let y = 0; y < TS; y++) for (let x = 0; x < TS; x++) {
      const X = (wx & 7) * TS + x + 128, Y = (wy & 7) * TS + y + 128;
      // overlapping round clumps, each lit on top
      const cx = Math.floor(X / 10), cy = Math.floor(Y / 10); let d1 = 9, by = 0;
      for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) { const hx = cx + i, hy = cy + j, pxx = hx * 10 + RW.hash2(hx & 15, hy & 15, 81) * 8, pyy = hy * 10 + RW.hash2(hx & 15, hy & 15, 82) * 8, d = Math.hypot(X - pxx, Y - pyy); if (d < d1) { d1 = d; by = Y - pyy; } }
      if ((open & 1) && y < 5 && d1 > 5 - y) continue;            // ragged top edge
      if ((open & 2) && y > 10 && d1 > 5 - (15 - y)) continue;     // ragged bottom edge
      let lv = 2 - by / 4; if (d1 > 6) lv = 0; if (RW.hash2(X, Y, 83) > 0.96) lv += 1;
      px(g, x, y, LEAFB[RW.clamp(Math.round(lv), 0, 4)]);
    }
    leafBCache.set(key, c); return c;
  }

  // the giant trees' crowns: lush clumps of leaves, lit from above, ragged where they meet the sky
  const LEAFF = ['#173414', '#1f461a', '#2a5c22', '#3a782c', '#4e9636', '#6cb446', '#94d064'];
  const canopyCache = new Map();
  function canopyTile(wx, wy, open) {
    const key = (wx & 7) + ',' + (wy & 7) + ',' + open; let c = canopyCache.get(key); if (c) return c;
    c = mk(TS + 4, TS + 4); const g = c.ctx;
    for (let y = -2; y < TS + 2; y++) for (let x = -2; x < TS + 2; x++) {
      const X = (wx & 7) * TS + x + 128, Y = (wy & 7) * TS + y + 128;
      const cx = Math.floor(X / 9), cy = Math.floor(Y / 9); let d1 = 9, by = 0, bx = 0, hue = 0;
      for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) { const hx = cx + i, hy = cy + j, px0 = hx * 9 + RW.hash2(hx & 15, hy & 15, 61) * 7, py0 = hy * 9 + RW.hash2(hx & 15, hy & 15, 62) * 7, d = Math.hypot(X - px0, Y - py0) - RW.hash2(hx & 15, hy & 15, 63) * 1.5; if (d < d1) { d1 = d; by = Y - py0; bx = X - px0; hue = RW.hash2(hx & 15, hy & 15, 64); } }
      const out = x < 0 || y < 0 || x >= TS || y >= TS;
      if (out) { const side = (y < 0 && (open & 1)) || (y >= TS && (open & 2)) || (x < 0 && (open & 4)) || (x >= TS && (open & 8)); if (!side || d1 > 4.2) continue; }
      if ((open & 1) && y < 4 && d1 > 6.2 - y) continue;
      if ((open & 2) && y > 11 && d1 > 6.2 - (15 - y)) continue;
      if ((open & 4) && x < 4 && d1 > 6.2 - x) continue;
      if ((open & 8) && x > 11 && d1 > 6.2 - (15 - x)) continue;
      // each clump: bright on its upper left, dark underneath, a dark crease between clumps
      let lv = 3.2 - by / 2.6 - bx / 7 + (hue - 0.5) * 0.8; if (d1 > 5.2) lv = 0.6; else if (d1 > 4.4) lv -= 1.2;
      if (by < -3 && bx < 1 && d1 < 3.4 && RW.hash2(X, Y, 65) > 0.55) lv += 1;      // little glints of sun on leaves
      px(g, x + 2, y + 2, LEAFF[RW.clamp(Math.round(lv), 0, 6)]);
    }
    canopyCache.set(key, c); return c;
  }

  // ---------- decor drawers ----------
  const X = A.decorExtra;
  const sway = (time, wx, wy, amp) => Math.sin(time * 1.3 + wx * 0.9 + wy * 0.3) * amp;
