    const floorY = Math.round(jungleH(L.jEnd - 8)) + 1;
    for (let x = L.jEnd - 6; x < L.cliff; x++) { for (let y = 0; y < floorY; y++) { c.set(x, y, T.air); c.setb(x, y, 0); } for (let y = floorY; y < floorY + 6; y++) { c.set(x, y, y === floorY ? T.jgrass : T.mud); c.setb(x, y, WL.mud); } c.surf[x] = floorY; }
    for (let x = L.cliff; x < L.cliff + 3; x++) { for (let y = HT; y < floorY + 4; y++) { c.set(x, y, y === HT ? T.grass : T.stone); c.setb(x, y, WL.dirt); } c.surf[x] = HT; }
